sql_query:
SELECT "Treatment regimen"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Treatment regimen", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Monotherapy/combination", '')) = 'Combination' AND TRIM(COALESCE("Name of ICI", '')) = 'Ipilimumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 2' AND TRIM(COALESCE("Type of combination", '')) = 'ICI+Chemo';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Treatment regimen" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Treatment regimen", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Monotherapy/combination", '')) = 'Combination' AND TRIM(COALESCE("Name of ICI", '')) = 'Ipilimumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 2' AND TRIM(COALESCE("Type of combination", '')) = 'ICI+Chemo'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_added_agents(source_value) AS "added_agents"
FROM base;
